insert into public.products (id, name, description, price, category, image, stock, featured, low_stock_threshold, cost_price) values
  ('1', 'موتور آسانسور ۶ نفره', 'موتور گیربکس‌دار با توان بالا مناسب ساختمان‌های مسکونی تا ۶ طبقه. این موتور با تکنولوژی پیشرفته اروپایی ساخته شده و دارای گارانتی ۲ ساله است. قدرت بالا، صدای کم و مصرف انرژی بهینه از ویژگی‌های بارز این محصول می‌باشد.', 45000000, 'موتور آسانسور', 'https://image.qwenlm.ai/generated-images/4a2a0de9-1993-44bf-a8ca-73047b6d2967/_result.png', 12, true, null, null),
  ('2', 'تابلو فرمان آسانسور دیجیتال', 'تابلو فرمان تمام دیجیتال با قابلیت تنظیمات پیشرفته و عیب‌یابی خودکار. این تابلو فرمان با میکروکنترلرهای پیشرفته طراحی شده و قابلیت اتصال به سیستم‌های هوشمند ساختمان را دارد.', 18000000, 'تابلو فرمان', 'https://image.qwenlm.ai/generated-images/75db95a8-6108-4b17-b717-1a1b4fff2b7c/_result.png', 25, true, null, null),
  ('3', 'ریلس T89/A (۳ متر)', 'ریلس استاندارد T89/A با طول ۳ متر، ساخت ایران با کیفیت بالا. این ریلس از فولاد مخصوص ساخته شده و دارای پوشش ضد زنگ می‌باشد. مناسب برای انواع آسانسورهای مسکونی و تجاری.', 2500000, 'ریلس و ریل‌براکت', 'https://image.qwenlm.ai/generated-images/f80f14c1-bd6c-45e1-bfb0-e926c2c15e11/_result.png', 50, false, null, null),
  ('4', 'سیم بکسل ۸ میلیمتر', 'سیم بکسل فولادی ۸ میلیمتر با روکش گالوانیزه، مناسب آسانسور. این سیم بکسل دارای مقاومت کششی بالا و عمر طولانی است. مطابق با استانداردهای بین‌المللی EN 81 تولید شده است.', 850000, 'سیم بکسل', 'https://image.qwenlm.ai/generated-images/f0cf54ed-9a12-48bb-a13a-6fd24ebccf62/_result.png', 100, true, null, null),
  ('5', 'درب اتوماتیک تلسکوپی', 'درب اتوماتیک تلسکوپی با سنسور ایمنی و موتور قدرتمند. این درب دارای سیستم ضد برخورد و تشخیص مانع می‌باشد. نصب آسان و نگهداری کم از مزایای این محصول است.', 32000000, 'درب آسانسور', 'https://image.qwenlm.ai/generated-images/47b15d6a-1643-47e1-a0cf-1aaa5a29d8c1/_result.png', 8, true, null, null),
  ('6', 'کابین استیل طلایی', 'کابین آسانسور با روکش استیل طلایی و آینه قدی، لوکس و مدرن. این کابین با طراحی خاص و متریال درجه یک ساخته شده و جلوه‌ای باشکوه به ساختمان می‌بخشد.', 55000000, 'کابین و دکوراسیون', 'https://image.qwenlm.ai/generated-images/299d9446-4d2e-4b4e-91ac-a51196e4bd41/_result.png', 5, true, null, null),
  ('7', 'اینورتر آسانسور', 'اینورتر VVVF با قابلیت تنظیم سرعت و کاهش مصرف انرژی. این اینورتر با تکنولوژی پیشرفته باعث کاهش ۴۰ درصدی مصرف برق و حرکت نرم و بی‌صدا می‌شود.', 22000000, 'قطعات الکتریکی', 'https://image.qwenlm.ai/generated-images/37a9487b-8b9d-48f6-a584-2981054fd593/_result.png', 15, false, null, null),
  ('8', 'ترمز الکترومکانیکی', 'ترمز الکترومکانیکی با قدرت توقف بالا و عمر طولانی. این ترمز با سیستم ایمنی پیشرفته مجهز شده و در مواقع اضطراری به سرعت عمل می‌کند.', 8500000, 'قطعات مکانیکی', 'https://image.qwenlm.ai/generated-images/b6a037b9-ae75-483a-93e0-5c460765d4a0/_result.png', 20, false, null, null),
  ('9', 'پاراشوت (ترمز اضطراری)', 'سیستم پاراشوت ایمنی برای جلوگیری از سقوط کابین. این سیستم حیاتی در مواقع قطع سیم بکسل یا خرابی ترمز اصلی، کابین را به صورت ایمن متوقف می‌کند.', 12000000, 'سیستم ایمنی', 'https://image.qwenlm.ai/generated-images/8262c0e2-36a9-48c8-8ef0-11aea40ff9da/_result.png', 18, true, null, null),
  ('10', 'چشمی درب آسانسور', 'چشمی فتوالکتریک برای تشخیص مانع در مسیر درب. این سنسور با دقت بالا مانع از برخورد درب با افراد یا اشیاء می‌شود و ایمنی را تضمین می‌کند.', 1500000, 'لوازم جانبی', 'https://image.qwenlm.ai/generated-images/4e1ddc57-24b9-43ba-833c-6dd46333c795/_result.png', 40, false, null, null),
  ('11', 'شستی احضار طبقات', 'شستی لمسی احضار طبقات با نمایشگر LED و طراحی مدرن. این شستی با تکنولوژی خازنی ساخته شده و دارای نور پس‌زمینه LED می‌باشد.', 3500000, 'قطعات الکتریکی', 'https://image.qwenlm.ai/generated-images/3e5d9a3b-d2e5-447d-b109-3aa19b3f1200/_result.png', 30, false, null, null),
  ('12', 'موتور بدون گیربکس (Gearless)', 'موتور گیرلس با راندمان بالا، صدای کم و مصرف انرژی پایین. این موتور نسل جدید آسانسورها بوده و با حذف گیربکس، راندمان را به ۹۵ درصد رسانده است.', 65000000, 'موتور آسانسور', 'https://image.qwenlm.ai/generated-images/bc73ed9f-5274-47f5-b945-3ae7a6c28f1a/_result.png', 6, true, null, null),
  ('13', 'گاورنر (سرعت‌سنج)', 'دستگاه گاورنر برای کنترل سرعت آسانسور و جلوگیری از حرکت بیش از حد. این دستگاه حیاتی در سیستم ایمنی آسانسور نقش کلیدی دارد.', 9500000, 'سیستم ایمنی', 'https://image.qwenlm.ai/generated-images/c5ccd7fa-5105-4714-9883-f104fd18409d/_result.png', 15, false, null, null),
  ('14', 'موتور اپراتور درب', 'موتور مخصوص درب آسانسور با گیربکس داخلی، قدرتمند و کم‌صدا. مناسب برای درب‌های اتوماتیک تلسکوپی و لولایی.', 12500000, 'درب آسانسور', 'https://image.qwenlm.ai/generated-images/48521dc2-bf73-4e9d-8cc3-1bb4f8186b04/_result.png', 20, false, null, null),
  ('15', 'بافر ضربه‌گیر', 'بافر هیدرولیک یا فنری برای جذب ضربه در پایین چاهک آسانسور. این قطعه ایمنی حیاتی در مواقع سقوط احتمالی کابین عمل می‌کند.', 7800000, 'سیستم ایمنی', 'https://image.qwenlm.ai/generated-images/88f6d479-3a9f-4be3-a140-045528896c77/_result.png', 25, false, null, null),
  ('16', 'کابل مسافرتی (Traveling Cable)', 'کابل تخت چند رشته‌ای مخصوص آسانسور با کانکتورهای استاندارد. مناسب برای انتقال سیگنال و برق بین کابین و تابلو فرمان.', 1200000, 'قطعات الکتریکی', 'https://image.qwenlm.ai/generated-images/d621f277-a1e5-445f-9281-09e90103e709/_result.png', 80, false, null, null),
  ('17', 'باکس بازرسی روی کابین', 'جعبه کنترل بازرسی با دکمه توقف اضطراری و سوئیچ‌های بازرسی. مناسب برای تکنسین‌های servicing.', 4500000, 'قطعات الکتریکی', 'https://image.qwenlm.ai/generated-images/070c25bf-82da-404c-b0ef-1ba5ed3ec909/_result.png', 18, false, null, null),
  ('18', 'وزنه تعادل (Counterweight)', 'بلوک‌های وزنه چدنی برای تعادل کابین آسانسور. وزن دقیق بر اساس ظرفیت کابین محاسبه و تأمین می‌شود.', 350000, 'قطعات مکانیکی', 'https://image.qwenlm.ai/generated-images/29bbc822-bd41-44b4-a284-bf3d507a0fa6/_result.png', 200, false, null, null),
  ('19', 'قفل درب (Interlock)', 'قفل ایمنی درب طبقات با مکانیزم اینترلاک. این قطعه از باز شدن درب در زمانی که کابین در آن طبقه نیست جلوگیری می‌کند.', 2800000, 'سیستم ایمنی', 'https://image.qwenlm.ai/generated-images/90b2a8c9-6461-451b-8d39-3d01bc3a9d90/_result.png', 35, false, null, null),
  ('20', 'سنسور موقعیت مغناطیسی', 'سنسور مگنتی برای تشخیص موقعیت کابین با دقت بالا. مناسب برای سیستم‌های کنترل دقیق طبقات.', 1800000, 'قطعات الکتریکی', 'https://image.qwenlm.ai/generated-images/0c38f46b-3b80-41ee-85e2-a01418a14090/_result.png', 45, false, null, null),
  ('21', 'تلفن اضطراری آسانسور', 'سیستم ارتباط دوطرفه اضطراری با handset. در مواقع گیر کردن مسافران، امکان ارتباط با بیرون را فراهم می‌کند.', 5200000, 'سیستم ایمنی', 'https://image.qwenlm.ai/generated-images/4c451c20-3557-451a-a006-dad0ae069f2d/_result.png', 22, false, null, null),
  ('22', 'فلکه کششی (Sheave)', 'فلکه شیاردار فولادی برای سیم بکسل آسانسور. ماشین‌کاری دقیق با بالانس دینامیکی برای حرکت نرم و بی‌صدا.', 15000000, 'قطعات مکانیکی', 'https://image.qwenlm.ai/generated-images/b0e67af1-d5a6-4d6a-ae4f-d0d114ec44aa/_result.png', 10, true, null, null)
